from urllib.parse import quote


def _encode(value) -> str:
    """Convert a single value to its string form and percent-encode it."""
    if value is True:
        text = "true"
    elif value is False:
        text = "false"
    else:
        text = str(value)
    # ``quote`` leaves ASCII letters, digits and ``-._~`` untouched and writes
    # every other UTF-8 byte as ``%XX`` (uppercase), so a space becomes ``%20``.
    return quote(text, safe="")

